def _calibration(cal):
    loads = np.asarray(cal['true_channel_loads'], dtype=float)
    raw = np.asarray(cal['bridge_raw'], dtype=float)
    fit = np.linalg.lstsq(np.column_stack((np.ones(len(loads)), loads)), raw, rcond=None)[0]
    return (fit[0], np.linalg.solve(fit[1:], np.ones(loads.shape[1])))

def _prepare(dataset):
    (tr, te) = (dataset['train'], dataset['test'])
    x = _features(tr, te)
    (offset, total) = _calibration(dataset['calibration_load_cells'])
    n = len(tr['lab_id'])

    def coupon(data, features):
        return ((data['past_channel_raw'] - offset) @ total, (data['hold_channel_raw'] - offset) @ total, np.column_stack((np.ones(len(features)), features)))
    return (coupon(tr, x[:n]), coupon(te, x[n:]))

def _fit(coupon, dt, times, y, loss='cauchy', tuning=2.5):
    from itertools import combinations
    from scipy.optimize import least_squares
    (n, k) = y.shape
    (lo, hi) = np.log([0.05000001, 24.999999])
    bounds = (np.r_[lo, lo, np.full(7, -np.inf)], np.r_[hi, hi, np.full(7, np.inf)])

    def linear_seed(taus):
        a = _design(coupon, dt, times, taus).reshape(-1, 7)
        coef = np.linalg.lstsq(a, y.ravel(), rcond=None)[0]
        return (np.sum((a @ coef - y.ravel()) ** 2), np.r_[np.log(taus), coef])
    seeds = sorted((linear_seed(np.array(pair)) for pair in combinations((0.075, 0.15, 0.3, 0.55, 0.9, 1.6, 3.0, 6.0, 12.0, 22.0), 2)), key=lambda p: p[0])

    def residual(p):
        return _design(coupon, dt, times, np.exp(p[:2])) @ p[2:] - y

    def optimize(seed, scale, kind):
        return least_squares(lambda p: (residual(p) / scale).ravel(), seed, method='trf', bounds=bounds, loss=kind, x_scale='jac', max_nfev=130, ftol=1e-09)
    seed = seeds[0][1]

    def scales(p):
        r = residual(p)
        (curve, rate) = (r[:, :-1].ravel(), r[:, -1])
        return np.maximum([1.4826 * np.median(abs(v - np.median(v))) for v in (curve, rate)], 1e-08)

    def weights(s):
        return np.r_[np.repeat(s[0], k - 1), s[1]]
    if loss == 'linear':
        p = optimize(seed, np.ones(k), 'linear').x
    else:
        p = optimize(seed, 1.5 * weights(scales(seed)), 'soft_l1').x
        p = optimize(p, tuning * weights(scales(p)), loss).x
    order = np.argsort(p[:2])
    return (np.exp(p[:2][order]), np.r_[p[2:4][order], p[4:]])

def _stress(raw, q):
    raw = np.asarray(raw, dtype=float)
    x = np.clip((raw - q[0]) @ np.linalg.inv(q[1:5]), -3, 3)
    for _ in range(24):
        r = _bridge_basis(x) @ q - raw
        if np.max(abs(r)) < 1e-11:
            break
        j = q[1:5].T + 3 * x[..., None, :] ** 2 * q[5:9].T + np.roll(x, -1, axis=-1)[..., None, :] * q[9:13].T + np.roll(x[..., None, :] * q[9:13].T, 1, axis=-1)
        dx = np.linalg.solve(j, r[..., None])[..., 0]
        x -= dx / np.maximum(1, np.max(abs(dx), axis=-1, keepdims=True))
    return x.sum(axis=-1)
